# 2. Abstract
old_abs = r"""\begin{abstract}
Deploying lightweight convolutional neural networks on micro-edge embedded devices enables automated precision poultry disease surveillance in low-connectivity rural agricultural facilities. However, post-training INT8 quantization—the prevailing edge compression standard—exhibits catastrophic accuracy failure on depthwise-separable topologies. In this paper, we localize, mathematically diagnose, and mitigate this quantization collapse across MobileNetV2, ShuffleNetV2, and EfficientNet-B0 on a verified leak-free dataset. First, an algorithmic perceptual hash audit ($D_H \le 5$) of published poultry benchmarks uncovered 617 near-duplicate pairs (including 156 cross-partition train-test duplicates), revealing an empirical optimistic evaluation bias (+0.03\% overall and +0.15\% on duplicate subsets) and establishing an 8,153-image sterile benchmark ($n=1,728$ test samples). While dynamic INT8 preserves MobileNetV2 (97.11\%) and ShuffleNetV2 (97.45\%), it collapses EfficientNet-B0 from 98.55\% to 10.42\%, where 97.0\% of predictions degenerate into Newcastle Disease. Layer-wise signal-to-quantization-noise ratio (SQNR) formulation demonstrates that cross-channel weight variance in depthwise convolutions ($\Delta_w \approx 14.8$) degrades effective bit-width to $B_{\text{eff}} \le 4.09$ bits and depthwise SQNR to 8.4\,dB under per-tensor scaling. We formulate a static per-channel Quantize-Dequantize (QDQ) calibration protocol that restores diagnostic fidelity across architectures (EfficientNet-B0 to 94.56\%, MobileNetV2 to 97.74\%, and ShuffleNetV2 to 97.57\% with 94.33\% Newcastle Disease recall). Furthermore, structured channel pruning reveals that structural parameter removal immediately collapses minority sensitivity to 0.0\%, and unweighted fine-tuning starves minority recovery (31.21\% at 50\% sparsity); we demonstrate that 30-epoch class-weighted loss with FP32 teacher distillation recovers Newcastle Disease recall to 86.52\% [79.91\%, 91.20\%]. Finally, physical profiling on a Raspberry Pi 5 ARM Cortex-A76 under ONNX Runtime 1.29 reveals that dynamic INT8 incurs graph fragmentation across 357 disjoint operators, slowing execution by 2.19$\times$ to 2.47$\times$. In contrast, static per-channel QDQ fuses into native \texttt{QLinearConv} kernels with vector dot-product instructions, dominating the deployment Pareto frontier: 7.59\,ms on MobileNetV2 (131.8 FPS, 2.67$\times$ speedup) and 6.29\,ms on ShuffleNetV2 (159.1 FPS, 1.33$\times$ speedup) without accuracy degradation.
\end{abstract}"""

new_abs = r"""\begin{abstract}
Deploying lightweight convolutional neural networks on micro-edge embedded devices enables automated precision poultry disease surveillance in low-connectivity rural agricultural facilities. However, post-training INT8 quantization—the prevailing edge compression standard—exhibits catastrophic accuracy failure on depthwise-separable topologies. In this paper, we localize, mathematically diagnose, and mitigate this quantization collapse across MobileNetV2, ShuffleNetV2, and EfficientNet-B0 on a decontaminated, sterile benchmark. First, an algorithmic perceptual hash audit ($D_H \le 5$) of the 8,770-image public benchmark (Dianyo Hugging Face dataset derived from Zenodo 4628934) uncovered 617 near-duplicate pairs (including 156 cross-partition train-test duplicates), quantifying an empirical evaluation bias (+0.15 pp on duplicate frames, +0.03 pp overall) and yielding an 8,153-image sterile dataset ($n=1,728$ test samples). While dynamic INT8 preserves MobileNetV2 (97.11\%) and ShuffleNetV2 (97.45\%), it collapses EfficientNet-B0 from 98.55\% to 10.42\%, where 97.0\% of predictions degenerate into Newcastle Disease. Layer-wise signal-to-quantization-noise ratio (SQNR) formulation demonstrates that cross-channel weight variance in depthwise convolutions ($\Delta_w \approx 14.8$) degrades effective bit-width to $B_{\text{eff}} \le 4.09$ bits and depthwise SQNR to 8.4\,dB under per-tensor scaling. We formulate a static per-channel Quantize-Dequantize (QDQ) calibration protocol that restores diagnostic fidelity across architectures: EfficientNet-B0 reaches 94.56\%, while MobileNetV2 (97.74\%, McNemar $p=0.1489$) and ShuffleNetV2 (97.57\%, $p=0.6171$) match baseline FP32 accuracy within $\pm 0.18$ percentage points with 94.33\% Newcastle Disease recall [95\% CI: 89.20\%, 97.10\%]. Crucially, while 30\% structured channel pruning coupled with static QDQ achieves 145.4 FPS (6.88\,ms, 1.35\,MB), Newcastle Disease recall collapses to 53.90\%; class-weighted distillation recovers recall to 86.52\% [79.91\%, 91.20\%]. On Raspberry Pi 5 (8\,GB RAM), unpruned Static QDQ (7.59\,ms, 131.8 FPS, 94.33\% NCD recall) strictly dominates pruned alternatives, proving that channel pruning provides zero Pareto advantage on modern edge processors with multi-gigabyte memory.
\end{abstract}"""

assert old_abs in text, "old_abs not found"
text = text.replace(old_abs, new_abs)

# 3. Intro line 67
old_intro = r"""While high-performance edge single-board computers (such as the Raspberry Pi 5 with 8\,GB LPDDR4X RAM) possess sufficient memory bandwidth to execute uncompressed FP32 models in real time (exceeding 50 to 110 FPS), deployable micro-edge agricultural monitoring nodes (such as the Raspberry Pi Zero 2 W with 512\,MB RAM or low-power embedded microcontrollers) operate under stringent hardware constraints characterized by limited SRAM, restricted thermal envelopes, and tight electrical power budgets \cite{jacob2018quantization,wu2019tinyml}. On such resource-constrained micro-edge tiers, aggressive model compression through post-training quantization and channel pruning is indispensable to fit model weights into limited caches and minimize memory-bus energy."""

new_intro = r"""While high-performance edge single-board computers (such as the Raspberry Pi 5 with 8\,GB LPDDR4X RAM) possess sufficient memory bandwidth to execute uncompressed FP32 models in real time (exceeding 50 to 110 FPS), constrained micro-edge agricultural monitoring tiers (such as microcontrollers with sub-2\,MB SRAM) operate under tight hardware limits where aggressive model compression is indispensable to fit parameters into on-chip cache \cite{jacob2018quantization,wu2019tinyml}. However, on modern edge single-board computers with multi-gigabyte memory, storage footprint does not constrain execution, necessitating a rigorous re-examination of whether channel pruning or integer quantization provides genuine Pareto acceleration without compromising veterinary safety."""

assert old_intro in text, "old_intro not found"
